SET NOCOUNT ON; SELECT c.name, t.name AS typ, c.max_length FROM sys.columns c JOIN sys.types t ON t.user_type_id=c.user_type_id WHERE c.object_id=OBJECT_ID('bd_purchase_in') AND c.name LIKE N'%转ERP%'; SELECT c.name FROM sys.columns c WHERE c.object_id=OBJECT_ID('bl_pu_order') AND (c.name LIKE N'%单位%' OR c.name LIKE N'%存量%') ORDER BY c.column_id; SELECT TOP 5 l.[行号], l.[物料编码], l.[数量], l.[单价], l.[税率%], l.[规格型号] FROM bl_pu_order l WHERE l.[单据编号]=N'YJ-20260909-01' AND ISNULL(l.asp_cancel,'N')<>'Y';